<template><div class="finance-page"><el-tabs v-model="tab" @tab-change="loadTab">
<el-tab-pane label="收支总览" name="overview"><div class="summary"><el-card><small>本月收入</small><b class="income">{{money(summary?.income)}}</b></el-card><el-card><small>本月支出</small><b class="expense">{{money(summary?.expense)}}</b></el-card><el-card><small>本月结余</small><b>{{money(summary?.balance)}}</b></el-card></div><el-card><template #header><div class="header"><span>支出分类</span><el-date-picker v-model="month" type="month" value-format="YYYY-MM" @change="loadSummary"/></div></template><BaseChart :option="categoryOption"/></el-card></el-tab-pane>
<el-tab-pane label="交易明细" name="transactions"><el-card><template #header><div class="header"><span>标准交易</span><div><el-input v-model="filters.keyword" clearable placeholder="商户/摘要"/><el-select v-model="filters.direction" clearable placeholder="收支"><el-option label="收入" value="INCOME"/><el-option label="支出" value="EXPENSE"/></el-select><el-button @click="loadTransactions">查询</el-button></div></div></template><el-table :data="transactions"><el-table-column label="时间" width="180"><template #default="{row}">{{time(row.transactionTime)}}</template></el-table-column><el-table-column prop="merchant" label="商户"/><el-table-column prop="description" label="摘要" show-overflow-tooltip/><el-table-column label="方向" width="90"><template #default="{row}"><el-tag :type="row.direction==='INCOME'?'success':'warning'">{{row.direction==='INCOME'?'收入':'支出'}}</el-tag></template></el-table-column><el-table-column label="金额" width="120"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column label="分类" width="180"><template #default="{row}"><el-select :model-value="row.categoryId" placeholder="待确认" @change="onCategoryChange(row.id,$event)"><el-option v-for="item in categories.filter(c=>c.direction===row.direction)" :key="item.id" :label="item.categoryName" :value="item.id"/></el-select></template></el-table-column></el-table></el-card></el-tab-pane>
<el-tab-pane label="账单导入" name="imports"><el-card><template #header>上传官方账单</template><el-form inline><el-form-item label="账户"><el-select v-model="upload.accountId" style="width:180px"><el-option v-for="item in accounts" :key="item.id" :label="item.accountName" :value="item.id"/></el-select></el-form-item><el-form-item label="平台"><el-select v-model="upload.platform" style="width:130px"><el-option label="支付宝" value="ALIPAY"/><el-option label="微信" value="WECHAT"/><el-option label="银行卡" value="BANK"/></el-select></el-form-item><el-form-item><el-upload :auto-upload="false" :show-file-list="false" accept=".csv,.xls,.xlsx" :on-change="selectFile"><el-button>选择 CSV/XLSX</el-button></el-upload></el-form-item><el-button type="primary" :disabled="!upload.file||!upload.accountId" :loading="uploading" @click="preview">解析预览</el-button></el-form><el-alert title="仅导入官方导出的账单文件；不会读取支付密码、短信验证码或自动登录金融账户。" type="info" :closable="false"/></el-card><el-card v-if="previewData"><template #header><div class="header"><span>预览：共 {{previewData.totalCount}}，重复 {{previewData.duplicateCount}}，无效 {{previewData.invalidCount}}</span><el-button type="primary" :disabled="previewData.invalidCount>0" @click="confirm">确认导入</el-button></div></template><el-table :data="previewData.rows" max-height="480"><el-table-column prop="rowNumber" label="#" width="60"/><el-table-column prop="transactionTime" label="时间" width="180"/><el-table-column prop="merchant" label="商户"/><el-table-column prop="direction" label="收支" width="90"/><el-table-column prop="amount" label="金额" width="100"/><el-table-column label="状态" width="140"><template #default="{row}"><el-tag v-if="row.validationError" type="danger">{{row.validationError}}</el-tag><el-tag v-else-if="row.duplicateFlag" type="warning">重复</el-tag><el-tag v-else type="success">可导入</el-tag></template></el-table-column></el-table></el-card></el-tab-pane>
<el-tab-pane label="账户与规则" name="settings"><el-row :gutter="16"><el-col :span="12"><el-card><template #header><div class="header"><span>资金账户</span><el-button type="primary" @click="accountVisible=true">新增</el-button></div></template><el-table :data="accounts"><el-table-column prop="accountName" label="名称"/><el-table-column prop="accountType" label="类型"/><el-table-column prop="institution" label="机构"/></el-table></el-card></el-col><el-col :span="12"><el-card><template #header><div class="header"><span>分类规则</span><el-button type="primary" @click="ruleVisible=true">新增</el-button></div></template><el-table :data="rules"><el-table-column prop="ruleName" label="规则"/><el-table-column prop="keyword" label="关键词"/><el-table-column label="分类"><template #default="{row}">{{categoryName(row.categoryId)}}</template></el-table-column></el-table></el-card></el-col></el-row></el-tab-pane>
</el-tabs>
<el-dialog v-model="accountVisible" title="新增资金账户" width="480px"><el-form :model="accountForm" label-width="90px"><el-form-item label="名称"><el-input v-model="accountForm.accountName"/></el-form-item><el-form-item label="类型"><el-select v-model="accountForm.accountType"><el-option label="支付宝" value="ALIPAY"/><el-option label="微信" value="WECHAT"/><el-option label="银行卡" value="BANK"/><el-option label="现金" value="CASH"/></el-select></el-form-item><el-form-item label="机构"><el-input v-model="accountForm.institution"/></el-form-item></el-form><template #footer><el-button @click="accountVisible=false">取消</el-button><el-button type="primary" @click="saveAccount">保存</el-button></template></el-dialog>
<el-dialog v-model="ruleVisible" title="新增分类规则" width="480px"><el-form :model="ruleForm" label-width="90px"><el-form-item label="名称"><el-input v-model="ruleForm.ruleName"/></el-form-item><el-form-item label="关键词"><el-input v-model="ruleForm.keyword"/></el-form-item><el-form-item label="分类"><el-select v-model="ruleForm.categoryId"><el-option v-for="item in categories" :key="item.id" :label="item.categoryName" :value="item.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="ruleVisible=false">取消</el-button><el-button type="primary" @click="saveRule">保存</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">import type{EChartsOption}from'echarts';import type{UploadFile}from'element-plus';import{ElMessage}from'element-plus';import{computed,onMounted,reactive,ref}from'vue';import BaseChart from'@/components/BaseChart.vue';import{categorizeFinanceTransaction,confirmFinanceImport,getFinanceMonthly,listFinanceAccounts,listFinanceCategories,listFinanceRules,listFinanceTransactions,previewFinanceImport,saveFinanceAccount,saveFinanceRule,type FinanceAccount,type FinanceCategory,type FinanceRule,type FinanceTransaction,type ImportPreview,type MonthlySummary}from'@/api/finance';const tab=ref('overview'),month=ref(new Date().toISOString().slice(0,7)),summary=ref<MonthlySummary>(),accounts=ref<FinanceAccount[]>([]),categories=ref<FinanceCategory[]>([]),rules=ref<FinanceRule[]>([]),transactions=ref<FinanceTransaction[]>([]),previewData=ref<ImportPreview>(),uploading=ref(false),accountVisible=ref(false),ruleVisible=ref(false);const filters=reactive({keyword:'',direction:''}),upload=reactive<{accountId?:number;platform:string;file?:File}>({platform:'ALIPAY'}),accountForm=reactive({accountName:'',accountType:'ALIPAY',institution:'',currency:'CNY',enabled:true}),ruleForm=reactive<{ruleName:string;keyword:string;categoryId?:number;priority:number;enabled:boolean}>({ruleName:'',keyword:'',priority:0,enabled:true});const categoryOption=computed<EChartsOption>(()=>({tooltip:{trigger:'item'},series:[{type:'pie',radius:['42%','70%'],data:(summary.value?.categories||[]).map(v=>({name:v.categoryName,value:v.amount}))}]}));async function base(){[accounts.value,categories.value,rules.value]=await Promise.all([listFinanceAccounts().then(r=>r.data),listFinanceCategories().then(r=>r.data),listFinanceRules().then(r=>r.data)]);if(!upload.accountId&&accounts.value.length)upload.accountId=accounts.value[0].id;}async function loadSummary(){summary.value=(await getFinanceMonthly(month.value)).data;}async function loadTransactions(){transactions.value=(await listFinanceTransactions({keyword:filters.keyword||undefined,direction:filters.direction||undefined})).data;}async function loadTab(name:string|number){if(name==='overview')await loadSummary();if(name==='transactions')await loadTransactions();if(name==='settings')await base();}function selectFile(file:UploadFile){upload.file=file.raw;}async function preview(){if(!upload.accountId||!upload.file)return;uploading.value=true;try{previewData.value=(await previewFinanceImport(upload.accountId,upload.platform,upload.file)).data;}finally{uploading.value=false;}}async function confirm(){if(!previewData.value)return;const count=(await confirmFinanceImport(previewData.value.batchId)).data;ElMessage.success(`成功导入 ${count} 条交易`);previewData.value=undefined;await Promise.all([loadTransactions(),loadSummary()]);}function onCategoryChange(id:number,value:unknown){void categorize(id,Number(value));}async function categorize(id:number,categoryId:number){await categorizeFinanceTransaction(id,categoryId);ElMessage.success('分类已确认');await loadTransactions();}async function saveAccount(){await saveFinanceAccount(accountForm);accountVisible.value=false;await base();}async function saveRule(){if(!ruleForm.categoryId)return;await saveFinanceRule({...ruleForm,categoryId:ruleForm.categoryId});ruleVisible.value=false;await base();}const categoryName=(id:number)=>categories.value.find(c=>c.id===id)?.categoryName||'-';const money=(v?:number)=>v==null?'-':`¥${Number(v).toFixed(2)}`;const time=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false});onMounted(async()=>{await base();await loadSummary();});</script>
<style scoped>.finance-page{display:flex;flex-direction:column;gap:16px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:16px}.summary small{display:block;color:#64748b}.summary b{display:block;font-size:26px;margin-top:10px}.income{color:#16a34a}.expense{color:#dc2626}.header{display:flex;justify-content:space-between;align-items:center}.header>div{display:flex;gap:8px}.header .el-input{width:180px}.header .el-select{width:120px}.el-card+.el-card{margin-top:16px}</style>
